@php
    $palette=[['#EEF2FF','#EEF2FF','#4338CA'],['#F0FDF4','#F0FDF4','#15803D'],['#FEFCE8','#FEFCE8','#A16207'],['#FFF7ED','#FFF7ED','#C2410C']];
    $columns=collect($ta->tahap)->flatMap(fn($s)=>$ta->componentsFor($s['id']))->values();
    $columnConfig=$columns->mapWithKeys(function($c) use($ta,$submissions){$stage=collect($ta->tahap)->firstWhere('id',$c['tahap_id'] ?? $ta->tahap[0]['id']);return [$c['id']=>['weight'=>$c['bobot'],'method'=>$stage['revisi_metode'] ?? 'rata_rata','initialWeight'=>$stage['revisi_bobot_awal'] ?? 50,'revision'=>(bool)($stage['revisi_aktif'] ?? false) || $submissions->where('tahap_id',$stage['id'])->contains(fn($s)=>$s->entries()->count()>1)]];})->all();
    $recapRows=$praktikan->values()->map(function($student,$i) use($ta,$grades,$attendance,$submissions){
        $grade=$grades->get($student->id);$presence=$attendance->get($student->id);
        $revisionStages=$submissions->where('praktikan_id',$student->id)->filter(fn($s)=>$s->entries()->count()>1)->pluck('tahap_id');
        $scores=collect($ta->komponen)->mapWithKeys(fn($c)=>[$c['id']=>(string)($grade?->initialScores()[$c['id']] ?? '')])->all();
        $revisions=collect($ta->komponen)->filter(fn($c)=>$revisionStages->contains($c['tahap_id'] ?? $ta->tahap[0]['id']))->mapWithKeys(fn($c)=>[$c['id']=>(string)($grade?->revisionScores()[$c['id']] ?? '')])->all();
        return ['id'=>$i,'student'=>$student->id,'name'=>mb_strtolower($student->user?->name ?? ''),'nim'=>(string)($student->user?->student?->student_number ?? ''),'kel'=>(string)($student->kelompok ?? ''),'shf'=>(string)($student->shift ?? ''),'scores'=>$scores,'revisions'=>$revisions,'version'=>$grade?->version ?? 0,'status'=>$presence?->status ?? '','note'=>$presence?->keterangan ?? '','attendanceVersion'=>$presence?->version ?? 0];
    });
@endphp
<div x-data="{
    columnOptions:{{ $columns->map(fn($c)=>['value'=>$c['id'],'label'=>(collect($ta->tahap)->firstWhere('id',$c['tahap_id'] ?? $ta->tahap[0]['id'])['nama']).' — '.$c['nama']])->values()->toJson() }},
    page:1,perPage:10,config:{{ json_encode($columnConfig) }},validWeights:{{ $ta->validWeights()?'true':'false' }},rows:{{ $recapRows->toJson() }},initial:[],
    init(){this.initial=JSON.parse(JSON.stringify(this.rows));this.registerExtraSave('ta',()=>this.dirty,()=>this.save());this.$watch('globalSearch',()=>this.page=1);this.$watch('globalKelompok',()=>this.page=1);this.$watch('globalShift',()=>this.page=1)},
    same(a,b){return JSON.stringify(a,(_,v)=>typeof v==='number'||(typeof v==='string' &amp;&amp; /^\d+(\.\d*)?$/.test(v))?String(Number(v)):v)===JSON.stringify(b,(_,v)=>typeof v==='number'||(typeof v==='string' &amp;&amp; /^\d+(\.\d*)?$/.test(v))?String(Number(v)):v)},
    gradeDirty(r){const old=this.initial[r.id];return !this.same(r.scores,old.scores)||!this.same(r.revisions,old.revisions)},
    attendanceDirty(r){const old=this.initial[r.id];return r.status!==old.status || r.note!==old.note},
    effective(r,key){const a=Number(r.scores[key]||0),revision=r.revisions[key],c=this.config[key];if(revision==null||revision==='')return a;const b=Number(revision);if(c.method==='ganti')return b;if(c.method==='tertinggi')return Math.max(a,b);if(c.method==='berbobot')return (a*Number(c.initialWeight)+b*(100-Number(c.initialWeight)))/100;return (a+b)/2},
    display(value){return Number.isFinite(Number(value)) ? Number(value).toFixed(2).replace('.',',') : '—'},
    average(r){return this.validWeights ? this.display(Object.entries(this.config).reduce((total,[key,c])=>total+this.effective(r,key)*Number(c.weight||0)/100,0)) : '—'},
    methodShort(key){return ({ganti:'Nilai revisi',tertinggi:'Tertinggi',berbobot:'Berbobot',rata_rata:'Rata-rata'})[this.config[key].method]||'Rata-rata'},
    methodLabel(key){const c=this.config[key];return ({ganti:'Nilai revisi',tertinggi:'Nilai tertinggi',rata_rata:'Rata-rata awal dan revisi',berbobot:'Berbobot '+c.initialWeight+'% : '+(100-c.initialWeight)+'%'})[c.method]||'Rata-rata awal dan revisi'},
    bulkOpen:false,bulkFields:[],bulkTarget:'awal',bulkNumbers:'',bulkValue:'',bulkError:'',bulkNotice:'',
    applyBulk(){this.bulkError='';if(!this.bulkFields.length){this.bulkError='Pilih minimal satu kolom penilaian.';return}const normalized=String(this.bulkValue).replace(',','.');if(!/^\d{1,3}(\.\d{0,2})?$/.test(normalized)||Number(normalized)>100){this.bulkError='Masukkan nilai 0–100.';return}const numbers=new Set();for(const part of this.bulkNumbers.replace(/[–—]/g,'-').split(',')){const match=part.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!match){this.bulkError='Format nomor tidak valid.';return}const from=Number(match[1]),to=Number(match[2]||match[1]);if(from<1||to<from||to>this.visibleRows.length){this.bulkError='Nomor di luar hasil pencarian saat ini.';return}for(let n=from;n<=to;n++)numbers.add(n)}let changed=0,skipped=0;for(const n of numbers){const r=this.visibleRows[n-1];for(const key of this.bulkFields){if(this.bulkTarget==='revisi'){if(!Object.hasOwn(r.revisions,key)){skipped++;continue}r.revisions[key]=normalized}else r.scores[key]=normalized;changed++}}if(!changed){this.bulkError='Tidak ada mahasiswa yang memenuhi syarat untuk nilai revisi pada pilihan ini.';return}this.bulkNotice=changed+' sel diterapkan'+(skipped?', '+skipped+' sel revisi dilewati karena belum dikumpulkan':'')+'. Klik Simpan untuk menyimpan perubahan.';this.bulkOpen=false;this.selectedCells=[];this.bulkValue='';this.bulkNumbers='';this.bulkError=''},
    selecting:false,selectionStart:null,selectionTarget:'awal',selectedCells:[],
    assessmentOptions(){return this.columnOptions},assessmentLabel(key){return this.columnOptions.find(c=>c.value===key)?.label||'Pilih kolom penilaian'},
    availableAssessmentOptions(index){return this.columnOptions.filter(c=>this.bulkFields[index]===c.value||!this.bulkFields.includes(c.value))},
    addAssessmentField(){const next=this.columnOptions.find(c=>!this.bulkFields.includes(c.value));if(next)this.bulkFields.push(next.value)},removeAssessmentField(index){this.bulkFields.splice(index,1)},
    openBulk(){if(!this.bulkFields.length &amp;&amp; this.columnOptions.length)this.bulkFields=[this.columnOptions[0].value];this.bulkError='';this.bulkOpen=true;this.$nextTick(()=>this.$refs.bulkValueInput?.focus())},
    closeBulk(){this.bulkOpen=false;this.selectedCells=[];this.bulkError='';this.bulkValue='';this.bulkNumbers=''},
    isSelected(r,key){return this.selectedCells.some(c=>c.id===r.id &amp;&amp; c.key===key)},
    beginSelection(r,key,target='awal'){if({{ $praktikum->is_active?'false':'true' }})return;if(target==='revisi' &amp;&amp; !Object.hasOwn(r.revisions,key))return;this.selecting=true;this.selectionTarget=target;this.selectionStart={id:r.id,key};this.extendSelection(r,key)},
    extendSelection(r,key){if(!this.selecting||!this.selectionStart)return;const rows=this.paginatedRows,keys=Object.keys(this.config),a=rows.findIndex(x=>x.id===this.selectionStart.id),b=rows.findIndex(x=>x.id===r.id),c=keys.indexOf(this.selectionStart.key),d=keys.indexOf(key);if(Math.min(a,b,c,d)<0)return;const selected=[];for(let i=Math.min(a,b);i<=Math.max(a,b);i++)for(let j=Math.min(c,d);j<=Math.max(c,d);j++){if(this.selectionTarget==='revisi' &amp;&amp; !Object.hasOwn(rows[i].revisions,keys[j]))continue;selected.push({id:rows[i].id,key:keys[j]})}this.selectedCells=selected},
    numberRanges(numbers){const ranges=[];let start=numbers[0],end=start;for(let i=1;i<=numbers.length;i++){if(numbers[i]===end+1){end=numbers[i];continue}ranges.push(start===end?String(start):start+'-'+end);start=end=numbers[i]}return ranges.join(', ')},
    finishSelection(){if(!this.selecting)return;this.selecting=false;this.selectionStart=null;if(this.selectedCells.length<2){this.selectedCells=[];return}this.bulkFields=[...new Set(this.selectedCells.map(c=>c.key))];this.bulkNumbers=this.numberRanges([...new Set(this.selectedCells.map(c=>this.visibleRows.findIndex(r=>r.id===c.id)+1))].sort((a,b)=>a-b));this.bulkTarget=this.selectionTarget;this.bulkValue='';this.openBulk()},
    get dirty(){return this.rows.some(r=>this.gradeDirty(r)||this.attendanceDirty(r))},
    get visibleRows(){return this.rows.filter(r=>(this.globalSearch===''||r.name.includes(this.globalSearch.toLowerCase())||r.nim.includes(this.globalSearch)) &amp;&amp; (this.globalKelompok===''||r.kel===this.globalKelompok) &amp;&amp; (this.globalShift===''||r.shf===this.globalShift))},
    get paginatedRows(){return this.visibleRows.slice((this.page-1)*this.perPage,this.page*this.perPage)},get totalPages(){return Math.max(1,Math.ceil(this.visibleRows.length/this.perPage))},
    span(index,type){const rows=this.paginatedRows;const i=rows.findIndex(r=>r.id===index);if(i<0)return 0;const same=(a,b)=>a.shf===b.shf &amp;&amp; (type==='shf'||a.kel===b.kel);if(i>0 &amp;&amp; same(rows[i-1],rows[i]))return 0;let size=1;while(i+size<rows.length &amp;&amp; same(rows[i],rows[i+size]))size++;return size},
    async save(){const students={};for(const r of this.rows){const row={};if(this.gradeDirty(r))row.grade={version:r.version,skor:Object.fromEntries(Object.entries(r.scores).map(([k,v])=>[k,v===''?null:v])),kosongkan:Object.fromEntries(Object.entries(r.scores).filter(([k,v])=>v==='' &amp;&amp; this.initial[r.id].scores[k]!=='').map(([k])=>[k,true])),revisi:Object.fromEntries(Object.entries(r.revisions).filter(([,v])=>v!==''))};if(this.attendanceDirty(r)){if(!r.status)throw new Error('Pilih kehadiran tugas akhir sebelum menyimpan keterangan.');row.attendance={version:r.attendanceVersion,status:r.status,keterangan:r.note}}if(Object.keys(row).length)students[r.student]=row}if(!Object.keys(students).length)return;const res=await fetch({{ json_encode(route($base.'save-recap',$routeArgs)) }},{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':{{ json_encode(csrf_token()) }}},body:JSON.stringify({students})});if(!res.ok){const data=await res.json();throw new Error(Object.values(data.errors||{}).flat().join(' ')||data.message||'Gagal menyimpan tugas akhir.')}}
}" @mouseup.window="finishSelection()">
